package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 创建实验请求：固定 2~8 个区组，每组 4 个席位，按提交顺序携带两个 A 和两个 B 处理代码。
 */
public record CreateExperimentRequest(
        @NotBlank String requestId,
        @NotBlank String experimentId,
        @NotNull @Size(min = 2, max = 8) List<@Size(min = 4, max = 4) List<@NotBlank String>> blocks) {
}

package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 参与者登记请求：首次登记原子领取按区组、席位顺序排列的第一个空位。
 */
public record AssignRequest(
        @NotBlank String requestId,
        @NotBlank String participantId) {
}

package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 仅携带幂等 requestId 的写操作请求（退组、关闭、批准揭盲）。
 */
public record RequestIdOnlyRequest(@NotBlank String requestId) {
}

package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 揭盲申请请求：协调员为已分配参与者提出，必须携带原因。
 */
public record UnblindApplyRequest(
        @NotBlank String requestId,
        @NotBlank String participantId,
        @NotBlank String reason) {
}

