                createBody(rid(), "EXP-DUPID", 2));
        assertThat(dup.getResponse().getStatus()).isEqualTo(409);
    }

    // ---------- 权限 ----------

    @Test
    void roleEnforcement() throws Exception {
        // 审核员不能创建实验
        assertThat(post("/api/experiments", REVIEWER, "REVIEWER",
                createBody(rid(), "EXP-R1", 2)).getResponse().getStatus()).isEqualTo(403);
        createExperiment("EXP-R2", 2);
        // 审核员不能登记
        MvcResult assignByReviewer = mvc.perform(post("/api/experiments/EXP-R2/assignments")
                        .header("X-Actor-Id", REVIEWER).header("X-Role", "REVIEWER")
